insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('104648','test','Итоговое тестирование','guru-50011','{"id":"104648","title":"Итоговое тестирование","timeLimitSeconds":390,"passCount":13,"questions":[{"id":"104648-1","text":"Основа коктейля Настоящий Полковник?","type":"single","options":["ром Black Pearl Gold, ром Black Pearl Dark, абсент","ром Black Pearl Gold и Dark, ликер Triple Sec","Абсент, ром Black Pearl White, самбука"]},{"id":"104648-2","text":"Вермут Cinzano какого типа присутствует в карте?","type":"single","options":["Bianco / Rosso / Extra Dry","Bianco / Rossato / Extra Dry","Bianco / Rosso / Fiero"]},{"id":"104648-3","text":"Какой кордиал входит в коктейль Маша и Медведи?","type":"single","options":["кордиал земляника и шисо","кордиал малина и шишки","кордиал голубика и дягиль"]},{"id":"104648-4","text":"Сколько коктейлей входит в категорию Коктейли Campari?","type":"single","options":["четыре","три","пять"]},{"id":"104648-5","text":"Это вино точно есть в меню!","type":"single","options":["Pinot Grigio Alteno Италия","Chateau Argadens Rouge Bordeaux Superieur AOC Франция","Chateau la Caminade AOC Франция"]},{"id":"104648-6","text":"Новый биттер, который входит в коктейль Шприц?","type":"single","options":["Sarti Rosa","Tundra Bitter Mint","Cinzano Rosato"]},{"id":"104648-7","text":"Светлое фильтрованное пиво в меню?","type":"single","options":["Hoegaarden","ABBE Brune","Spaten muncher hell"]},{"id":"104648-8","text":"Вальдобиадене что это?","type":"single","options":["Метод купажа игристых вин","Винодельческая зона","Винный дом Графа Вальдо"]},{"id":"104648-9","text":"Новая текила, выбери верный вариант","type":"single","options":["Espolon Blanco / Gold","Jose Cuervo Especial Silver / Gold","Jose Cuervo Silver / Gold / Reposado"]},{"id":"104648-10","text":"Верный состав коктейля Крыжесносный?","type":"single","options":["пюре крыжовника, сироп жасмина, алоэ мед, сок яблочный, игристое безалкогольное","пюре крыжовника, сироп жасмина, алоэ мед, сок яблочный, Aqua Minerale","пюре крыжовника, сироп жасмина, сок яблочный, Evervess IndianTonic"]},{"id":"104648-11","text":"Новый итальчянский джин в меню?","type":"single","options":["Bickens London Dry Gin","Tanqueray London Dry Gin","Royal Raven Yuzu"]},{"id":"104648-12","text":"Основа коктейля Ограбление по Итальянски?","type":"single","options":["джин Green Baboon, водка Tundra Authentic","текила La Pavesa Plata, ликер Triple Sec","джин Green Baboon, вермут Cinzano Rosso"]},{"id":"104648-13","text":"К какой категории относится сидр?","type":"single","options":["Винный напиток, чтоже еще!","Слабоалкогольные игристые напитки категория","Фруктовое пиво"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('104593','test','Итоговое тестирование','guru-50012','{"id":"104593","title":"Итоговое тестирование","timeLimitSeconds":690,"passCount":23,"questions":[{"id":"104593-1","text":"С каким соусом подаются чесночные гренки?","type":"single","options":["Соус BBQ","Соус спайси","Сырный соус"]},{"id":"104593-2","text":"С чем подается теплый салат из щупалец кальмара?","type":"single","options":["С макаронами и сыром","С молодым картофелем и овощами","С рисом и брокколи"]},{"id":"104593-3","text":"Какой размер у «Клубной пиццы 90-е»?","type":"single","options":["33 см","30 см","22 см"]},{"id":"104593-4","text":"В состав салата «Тропикана женщина» входят:","type":"single","options":["Теплые креветки, соус из манго, кокосовое молоко и свежие ягоды","Жареные баклажаны и томаты","Копченая индейка и грейпфрут"]},{"id":"104593-5","text":"Какая граммовка у салата «Шеф развязал»?","type":"single","options":["160 гр","200 гр","180 гр"]},{"id":"104593-6","text":"С чем подается зеленый салат со слабосоленым лососем?","type":"single","options":["С грейпфрутом и авокадо","С яйцом пашот и соусом блю-чиз","С креветками и мидиями"]},{"id":"104593-7","text":"Под каким названием скрывается турецкая пицца с говядиной?","type":"single","options":["Попробуй джага-джага","Сам ты — Наташа!","Где фунтик?"]},{"id":"104593-8","text":"Какая лапша используется в пасте «Соба с морепродуктами»?","type":"single","options":["Пшеничная","Гречневая","Рисовая"]},{"id":"104593-9","text":"Под каким названием скрывается запечённый багет с пепперони, ветчиной и курицей?","type":"single","options":["Попробуй джага-джага","Сам ты — Наташа!","Где фунтик?"]},{"id":"104593-10","text":"Как называются мидии, запеченные с сыром и икрой тобико?","type":"single","options":["Мидии по-королевски","Мидии гранд киви","Мидийное место"]},{"id":"104593-11","text":"Какие морепродукты входят в состав супа Том Ям?","type":"single","options":["Только мидии","Креветки, мидии, кальмары, лосось","Только креветки"]},{"id":"104593-12","text":"Какие ингредиенты входят в состав тартара из мраморной говядины?","type":"single","options":["Говядина, авокадо и сливочный сыр","Каперсы, горчица и чипсы из батата","Ростбиф, сыр гауда и креветки"]},{"id":"104593-13","text":"С каким гарниром подается стейк лосося?","type":"single","options":["С жареным картофелем","С отварным рисом","С пюре из брокколи"]},{"id":"104593-14","text":"Какой сыр используется в салате «Круэлла-страчателла»?","type":"single","options":["Сыр дор-блю","Молодой сыр (страчателла)","Сыр гауда"]},{"id":"104593-15","text":"Что входит в состав салата «Один раз не нисуаз»?","type":"single","options":["Жареные креветки","Маринованный тунец","Копченая индейка"]},{"id":"104593-16","text":"Как называется тартар из лосося, который подается в вафельном стаканчике?","type":"single","options":["Жадина-говядина","Детям мороженое","Играем в бутылочку?"]},{"id":"104593-17","text":"Из меню «Малиновых пиджаков»: какие соусы можно выбрать к стейку Пиканья?","type":"single","options":["Только грибной и томатный","Мясной, горчичный, грибной","Только мясной и сырный"]},{"id":"104593-18","text":"В состав какого блюда входит паштет из шпрот?","type":"single","options":["Закуска 90-е","Трио брускетт","Лихие 90-е"]},{"id":"104593-19","text":"Какой соус используется в салате «Теплый баклажан»?","type":"single","options":["Понзу","Блю-чиз","Цезарь"]},{"id":"104593-20","text":"Из чего готовятся «Шары ярости»?","type":"single","options":["Из куриного филе в панировке","Из картофеля и грибов","Крокеты из снежного краба с сыром и соусом унаги"]},{"id":"104593-21","text":"Какое блюдо скрывается под названием «Но я тебе не дам!»?","type":"single","options":["Салат с ростбифом","Салат с тунцом","Зелёный салат с копчёной индейкой, авокадо и грейпфрутом"]},{"id":"104593-22","text":"Что подают в блюде с игривым названием «Играем в бутылочку?»?","type":"single","options":["Ростбиф, сыр гауда, сыр дор-блю, маслины, креветки, корнишоны и помидоры черри","Мидии, запеченные с сыром","Свиные ребра с соусом чили"]},{"id":"104593-23","text":"С каким соусом подаются сырные палочки «Палочка выручалочка»?","type":"single","options":["Унаги","Спайси","Сырный"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
