insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('106192','test','Тест Текила','guru-51132','{"id":"106192","title":"Тест Текила","timeLimitSeconds":300,"passCount":10,"questions":[{"id":"106192-1","text":"Крепость Jose Cuervo Silver?","type":"single","options":["38%","35%","42%","40%"]},{"id":"106192-2","text":"Лидер по продажам текилы в мире?","type":"single","options":["Espolon","La Pavesa","Agavita","Jose Cuervo"]},{"id":"106192-3","text":"Текила с выдержкой 2 месяца в дубе?","type":"single","options":["La Pavesa","Jose Cuervo Gold","Espolon Blanco","Espolon Reposado"]},{"id":"106192-4","text":"Популярный способ употребления серебрянной текилы вне Мексики?","type":"single","options":["Сангрита","Соль и лайм","Апельсин и корица","Морковь и малина"]},{"id":"106192-5","text":"Как называется сердцевина агавы?","type":"single","options":["Голд Харт","Пика","Пинья","Пульке"]},{"id":"106192-6","text":"Как началась история текилы по легенде?","type":"single","options":["Молния ударила в агаву","Конкистадоры","Монахи","Ацтеки вывели сорт"]},{"id":"106192-7","text":"\"Русская\" текила 100% агава»?","type":"single","options":["La Pavesa Plata","Espolon","Jose Cuervo","Agavita"]},{"id":"106192-8","text":"Как называют сборщиков голубой агавы?","type":"single","options":["Химадоры","Торсидоры","Кависты","Сомелье"]},{"id":"106192-9","text":"Минимальная выдержка Extra Añejo?","type":"single","options":["1 год","3 года","8 лет","2 года"]},{"id":"106192-10","text":"Минимальная доля спиртов агавы в Mixta?","type":"single","options":["81%","51%","75%","100%"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('108547','test','✅ Тест','guru-52664','{"id":"108547","title":"✅ Тест","timeLimitSeconds":750,"passCount":25,"questions":[{"id":"108547-1","text":"Один из самых растасканных на цитаты фильмов 90-х — про питерского парня, который «за своих» и произносит короткую фразу про то, где сила. Какая это фраза?","type":"single","options":["«Всё будет хорошо»","«Кто сильнее, тот и прав»","«Сила в правде»","«Мы за миром следим»"],"image":"assets/remaining-tests/7b0c115c6292e8194744ba21.jpg","images":["assets/remaining-tests/7b0c115c6292e8194744ba21.jpg"]},{"id":"108547-2","text":"В культовом сериале «Улицы разбитых фонарей» одного из ментов — Ларина по кличке «Казанова» — сыграл актёр, которого сейчас чаще видят в совсем других ролях. Кто это?","type":"single","options":["Александр Половцев","Сергей Селин","Алексей Нилов","Михаил Пореченков"],"image":"assets/remaining-tests/2ebc1644f9de5180b25a7477.jpg","images":["assets/remaining-tests/2ebc1644f9de5180b25a7477.jpg"]},{"id":"108547-3","text":"В 1997 году, до дефолта, что из перечисленного стоило дороже всего в среднем по стране?","type":"single","options":["Видеокассета с фильмом","Sega Mega Drive","Велосипед «Кама»","Джинсы Levi''s"],"image":"assets/remaining-tests/39cbde0c3caab93e9e7b8597.jpg","images":["assets/remaining-tests/39cbde0c3caab93e9e7b8597.jpg"]},{"id":"108547-4","text":"До дефолта 1998 года доллар стоил около 6 рублей. Примерно во сколько раз вырос курс к концу того же года после обвала рубля?","type":"single","options":["В 2 раза","В 4 раза (курс поднялся до ~20-24 рублей)","Не изменился","В 10 раз"],"image":"assets/remaining-tests/a2fb5148e68f2dda4dd2f604.jpg","images":["assets/remaining-tests/a2fb5148e68f2dda4dd2f604.jpg"]},{"id":"108547-5","text":"Этот певец на рубеже 80-90-х собирал стадионы, а фанатки устраивали настоящую истерику на концертах — уровень хайпа сравним разве что с нынешними К-поп айдолами. Как его звали?","type":"single","options":["Юра Шатунов","Влад Сташевский","Богдан Титомир","Александр Серов"],"image":"assets/remaining-tests/e776140e528331785bcb48c0.jpg","images":["assets/remaining-tests/e776140e528331785bcb48c0.jpg"]},{"id":"108547-6","text":"В августе 1991 года, во время попытки государственного переворота, будущий президент произнёс речь и стал героем культового кадра, забравшись на военную технику у Белого дома. О ком речь?","type":"single","options":["Егор Гайдар","Михаил Горбачёв","Александр Руцкой","Борис Ельцин"],"image":"assets/remaining-tests/51db940813e11650e0c12ced.jpg","images":["assets/remaining-tests/51db940813e11650e0c12ced.jpg"]},{"id":"108547-7","text":"До появления видеопроката на каждом углу существовал полуподпольный формат — квартиру или комнату оборудовали телевизором с видиком и пускали зрителей за деньги. Какой жанр фильмов там крутили чаще всего?","type":"single","options":["Документалистика","Мультфильмы Disney","Боевики с Ван Даммом, Чаком Норрисом и Брюсом Ли","Советская классика"],"image":"assets/remaining-tests/06fe09811b0eb58ecd8001f6.jpg","images":["assets/remaining-tests/06fe09811b0eb58ecd8001f6.jpg"]},{"id":"108547-8","text":"Фильм «Титаник» вышел в американский прокат в конце","type":"single","options":["1997","1998","2000","1999"],"image":"assets/remaining-tests/703560a4a3dabd047621911f.jpg","images":["assets/remaining-tests/703560a4a3dabd047621911f.jpg"]},{"id":"108547-9","text":"31 декабря 1999 года президент обратился к стране с неожиданным новогодним заявлением, объявив об отставке. Какую фразу из этого обращения помнят до сих пор?","type":"single","options":["«Извините за ошибки»","«Берегите Россию»","«Мы построили новую страну»","«Я устал, я ухожу»"],"image":"assets/remaining-tests/8d2d4259ff07bfe72304c443.jpg","images":["assets/remaining-tests/8d2d4259ff07bfe72304c443.jpg"]},{"id":"108547-10","text":"В 1974 году СССР подписал контракт с одной американской компанией, и её напиток первым из «капиталистических» газировок появился в советских магазинах — задолго до перестройки и первого Макдоналдса. Какой бренд обошёл всех конкурентов на десять лет вперёд?","type":"single","options":["Sprite","Pepsi","Coca-Cola","Fanta"],"image":"assets/remaining-tests/6e8b536ea0c17c68970f8865.jpg","images":["assets/remaining-tests/6e8b536ea0c17c68970f8865.jpg"]},{"id":"108547-11","text":"Если «копейка» (ВАЗ-2101) была машиной родителей, то настоящей мечтой молодёжи и признаком успеха в 90-е стала более новая модель — угловатая «зубило». Как её называли в народе?","type":"single","options":["«Волга»","«Копейка»","«Девятка»","«Ока»"],"image":"assets/remaining-tests/70407a820af8776aae7015a0.jpg","images":["assets/remaining-tests/70407a820af8776aae7015a0.jpg"]},{"id":"108547-12","text":"Этот предмет одежды никто специально не продвигал как символ 90-х — просто он был единственным реально доставаемым «фирменным» товаром и стал маркером статуса на районе. О чём речь?","type":"single","options":["Кроссовки Adidas с тремя полосками (часто паленые)","Кепки Puma","Джинсы Levi''s 501","Куртки-аляска"],"image":"assets/remaining-tests/d86992ed64804b0583a1c004.jpg","images":["assets/remaining-tests/d86992ed64804b0583a1c004.jpg"]},{"id":"108547-13","text":"Этот товар в 90-е считался «диким дефицитом» и предметом гордости, хотя производился в СССР в огромных количествах — просто плохо продавался/распределялся. Что это было?","type":"single","options":["Финская туалетная бумага","Бананы","Жвачка «Турбо»","Стущёнка"],"image":"assets/remaining-tests/085ed49b3bdd77f254c25fff.jpg","images":["assets/remaining-tests/085ed49b3bdd77f254c25fff.jpg"]},{"id":"108547-14","text":"Этот шоколадный десерт с игрушкой внутри был must-have у детей 90-х в России, при этом он официально запрещён к продаже в США и части других стран из-за риска подавиться мелкими деталями. Что это?","type":"single","options":["Киндер-сюрприз","Растишка","М&M''s","Чупа-чупс"],"image":"assets/remaining-tests/751577014325da3168511e6e.jpg","images":["assets/remaining-tests/751577014325da3168511e6e.jpg"]},{"id":"108547-15","text":"С 1991 года и следующие почти 30 лет одну из самых популярных телепередач страны — с барабаном, призами и капиталом за очки — вёл один и тот же человек. Кто это?","type":"single","options":["Валдис Пельш","Леонид Якубович","Николай Фоменко","Дмитрий Дибров"],"image":"assets/remaining-tests/cbc09344a3d29367d0c0b320.jpg","images":["assets/remaining-tests/cbc09344a3d29367d0c0b320.jpg"]},{"id":"108547-16","text":"До того как у всех появились мобильники, элитным гаджетом «для своих» был девайс, который просто присылал короткий текст на маленький экранчик — позвонить в ответ через него было нельзя. Что это?","type":"single","options":["Радиостанция","Мобильный телефон-«кирпич»","Автоответчик","Пейджер"],"image":"assets/remaining-tests/b61242a502431eee28ebd5b0.jpg","images":["assets/remaining-tests/b61242a502431eee28ebd5b0.jpg"]},{"id":"108547-17","text":"Герой знаменитой рекламы финансовой пирамиды МММ по имени Леня Голубков стал мемом задолго до появления мемов. Что, согласно рекламному ролику, он собирался купить жене на «нетрудовые доходы»?","type":"single","options":["Квартиру","Сапоги","Машину","Шубу"],"image":"assets/remaining-tests/17bddc72ecb68a711e4ae7eb.jpg","images":["assets/remaining-tests/17bddc72ecb68a711e4ae7eb.jpg"]},{"id":"108547-18","text":"Когда порошковые напитки типа Invite всем надоели, на рынке появился premium-сегмент — соки в необычных вкусах (манго, гуава), которые разливала российская компания «Вимм-Билль-Данн». Как назывался этот бренд?","type":"single","options":["17","Rich","«Моя семья»","«Добрый»"],"image":"assets/remaining-tests/2f80d8179b31bb3a0cd4fce1.jpg","images":["assets/remaining-tests/2f80d8179b31bb3a0cd4fce1.jpg"]},{"id":"108547-19","text":"В 1992 году каждый гражданин России получил документ, дающий право на долю госимущества — по сути, «акцию» на всю страну. Какая сумма (в рублях по ценам 1992 года) была номиналом этой бумаги?","type":"single","options":["1 000 000 рублей","10 000 рублей","1 000 рублей","100 000 рублей"],"image":"assets/remaining-tests/934de6f145cfbfa42efacbe1.jpg","images":["assets/remaining-tests/934de6f145cfbfa42efacbe1.jpg"]},{"id":"108547-20","text":"В бар зашли трое. Первый заказал безалкогольный мохито, второй — воду, третий — кофе. Бармен на автомате протягивает ключи от машины третьему, решив, что за рулём именно он. В чём его косяк?","type":"single","options":["Кофе тоже бодрит, поэтому логично","За рулём должен быть тот, кто заказал воду","Бармен прав, ошибки нет","По заказу нельзя определить, кто за рулём — трезвый вид не доказательство"],"image":"assets/remaining-tests/62a1715959ffe465d9337a0f.jpg","images":["assets/remaining-tests/62a1715959ffe465d9337a0f.jpg"]},{"id":"108547-21","text":"Расставь по порядку, что случилось раньше всего: (1) открытие первого Макдоналдса в Москве, (2) бум тамагоги, (3) деноминация рубля, (4) дефолт 1998 года.","type":"single","options":["Дефолт → Деноминация → Тамагоги → Макдоналдс","Тамагоги → Макдоналдс → Дефолт → Деноминация","Макдоналдс → Тамагоги → Деноминация → Дефолт","Деноминация → Дефолт → Макдоналдс → Тамагоги"],"image":"assets/remaining-tests/f9ab137997777bc034bfd32a.jpg","images":["assets/remaining-tests/f9ab137997777bc034bfd32a.jpg"]},{"id":"108547-22","text":"Этот московский ночной клуб середины 90-х (давший имя и одноимённый журналу) считался главной точкой на карте зарождающейся рейв- и техно-культуры в России. Как он назывался?","type":"single","options":["«Титаник»","«Метелица»","«Утопия»","«Птюч»"],"image":"assets/remaining-tests/5e4b09d5591395ac82d4483b.jpg","images":["assets/remaining-tests/5e4b09d5591395ac82d4483b.jpg"]},{"id":"108547-23","text":"Треники с лампасами и тремя полосками носили и школьники, и «бизнесмены». Но настоящим шиком считалась не сама марка, а особая деталь кроя, которую все специально не расстёгивали до конца. Что это было?","type":"single","options":["Молния на воротнике","Кнопки по бокам штанин (чтобы было видно кроссовки/носки под треники)","Карман на рукаве","Капюшон с завязками"],"image":"assets/remaining-tests/0ba80286b63b118650ce5a12.jpg","images":["assets/remaining-tests/0ba80286b63b118650ce5a12.jpg"]},{"id":"108547-24","text":"После деноминации, в 1998 году, на 100 рублей ещё можно было закрыть скромный поход в магазин. Что реалистичнее всего было купить на эту сумму?","type":"single","options":["Билет на самолёт по России","Джинсы Levi''s","Видеомагнитофон","Пакет продуктов на ужин (хлеб, молоко, сосиски, что-то к чаю)"],"image":"assets/remaining-tests/b2635a2961557281764af1bb.jpg","images":["assets/remaining-tests/b2635a2961557281764af1bb.jpg"]},{"id":"108547-25","text":"До деноминации 1998 года в кошельках лежали купюры с очень внушительным количеством нулей. Какого номинала купюра реально существовала в обороте в середине 90-х?","type":"single","options":["50 000 рублей","500 000 рублей","5 000 000 рублей","1 000 рублей"],"image":"assets/remaining-tests/cde4e694fa3b761fd2e88149.jpg","images":["assets/remaining-tests/cde4e694fa3b761fd2e88149.jpg"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('95472','test','Повышаем личные продажи','guru-44663','{"id":"95472","title":"Повышаем личные продажи","timeLimitSeconds":210,"passCount":7,"questions":[{"id":"95472-1","text":"Пользуясь методом \"Елочка\", что вы предложите очень голодному гостю?","type":"single","options":["Что-то, что быстро готовится","Сытные блюда из мяса, рыбы или птицы","Любые три самые дорогие блюда на выбор"],"image":"assets/remaining-tests/fa8501617a4d36074145be99.jpg","images":["assets/remaining-tests/fa8501617a4d36074145be99.jpg"]},{"id":"95472-2","text":"Какое предложение из перечисленных ниже является хорошо сделанным кросс-селлингом?","type":"single","options":["Не хотите сливки к кофе?","Мяту в чай добавить?","Хотите, заварю вам чай с чабрецом? Ароматный, согревающий - как раз для такой погоды!"],"image":"assets/remaining-tests/18eca08c0fffd1db92b7862a.jpg","images":["assets/remaining-tests/18eca08c0fffd1db92b7862a.jpg"]},{"id":"95472-3","text":"Какое из предложений ниже является качественно сделанным даунселлингом?","type":"single","options":["Я рекомендую вам взять полпорции тыквенного супа вместо целой, тогда вы сможете еще попробовать наш фирменный салат.","Не берите целую порцию, вам будет много.","Попробуйте еще наш салат! А чтобы не объесться, можете взять половину порции супа."],"image":"assets/remaining-tests/eeba777a4df382003a34cf96.jpg","images":["assets/remaining-tests/eeba777a4df382003a34cf96.jpg"]},{"id":"95472-4","text":"Какое предложение из перечисленных ниже является хорошо сделанным апселлингом?","type":"single","options":["Еще чего-нибудь желаете?","А хотите наш фирменный кофе вместо капучино? Готовится на основе эспрессо с ярким домашним апельсиновым сиропом и пенкой разной температуры! Такого больше нигде не попробуете.","Не хотите-ли большую пиццу вместо стандартной?"],"image":"assets/remaining-tests/840d9341e9d2174b37b020bc.jpg","images":["assets/remaining-tests/840d9341e9d2174b37b020bc.jpg"]},{"id":"95472-5","text":"Как называется метод продаж, при котором официант \"ведет\" гостя по меню, задавая наводящие вопросы, например \"Вы предпочитаете мясо, рыбу или курицу?\"","type":"single","options":["Кивок Салливана","Даунселлинг","Ёлочка","Апселлинг"],"image":"assets/remaining-tests/e1b696d5d6bf771dd968c9ea.jpg","images":["assets/remaining-tests/e1b696d5d6bf771dd968c9ea.jpg"]},{"id":"95472-6","text":"Какой из методов описан ниже? \"Продажа дополнительных позиций, расширение заказа. Суть этого метода в том, что официант предлагает попробовать дополнительные напитки, блюда.\"","type":"single","options":["Апселлинг","Крос-селлинг","Даунселлинг"],"image":"assets/remaining-tests/52f2499d29e2513e5f54b35b.jpg","images":["assets/remaining-tests/52f2499d29e2513e5f54b35b.jpg"]},{"id":"95472-7","text":"Что можно дополнительно предложить к кофе? Отметьте ВСЕ правильные ответы.","type":"multiple","options":["Сироп","Молоко","Сливки","Мини-десерт","Сахар"],"image":"assets/remaining-tests/f1e6b0dfb1e6cfa1942ec3cd.jpg","images":["assets/remaining-tests/f1e6b0dfb1e6cfa1942ec3cd.jpg"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('95473','test','Легендарный сервис','guru-44663','{"id":"95473","title":"Легендарный сервис","timeLimitSeconds":110,"passCount":3,"questions":[{"id":"95473-1","text":"Сколько стоила акция с фотографиями игрушки для сотрудников отеля?","type":"single","options":["100$","400$","0$"],"image":"assets/remaining-tests/bb80b3ca9ecaed3a030c1733.jpg","images":["assets/remaining-tests/bb80b3ca9ecaed3a030c1733.jpg"]},{"id":"95473-2","text":"На какой вопрос вы должны ответить сами себе, чтобы ваш сервис стал легендарным?","type":"single","options":["Какую акцию для гостей стоит придумать, чтобы публикаций в социальных сетях о ресторане стало больше?","А как я могу попросить гостя выложить пост обо мне в социальные сети?","А что я могу сделать для гостя, чтобы он рассказал всем о моем классном сервисе?"],"image":"assets/remaining-tests/6947bb4238ef001e34706b46.jpg","images":["assets/remaining-tests/6947bb4238ef001e34706b46.jpg"]},{"id":"95473-3","text":"Почему сотрудники Ritz Carlton не просто отправили Джошуа домой по почте, но придумали историю с развлечениями для игрушки?","type":"single","options":["Они хотели, чтобы малыш обрадовался тому, что у его любимой игрушки был отличный день, а родители малыша еще раз обратили внимание на то, какие услуги предоставляет отель.","Такое поведение с забытыми детскими игрушками прописано в их книге Стандартов и является обязательным.","Они хотели приобрести медийную известность, и надеялись на публикации в социальных сетях. Они рассчитывали таким образом поднять свой рейтинг в интернете."],"image":"assets/remaining-tests/a79fe309f73a5b04d8c4ef84.jpg","images":["assets/remaining-tests/a79fe309f73a5b04d8c4ef84.jpg"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('94526','test','Тест по кухням мира','guru-44033','{"id":"94526","title":"Тест по кухням мира","timeLimitSeconds":290,"passCount":9,"questions":[{"id":"94526-1","text":"Какой принцип лежит в основе высокой кухни (Haute Cuisine) Франции?","type":"single","options":["Французская высокая кухня полностью исключает использование мяса и рыбы","Баланс тонких вкусов, использование лучших продуктов и внимание к деталям в подаче","Главная особенность — простота и минимализм в приготовлении"]},{"id":"94526-2","text":"Какими словами можно описать русскую кухню? Выбери верные ответы","type":"multiple","options":["Простота блюд, наполненная уважением к природе и гостю","Ориентация на роскошные ингредиенты и изысканную сервировку","Региональное разнообразие","Акцент на экзотические ингредиенты и сложные техники приготовления","Связь с традицией, сезонностью и душевным застольем","Быстрота и удобство как основа ежедневного меню"]},{"id":"94526-3","text":"Какие особенности характерны для японских десертов?","type":"multiple","options":["Японские десерты всегда подаются горячими","Все традиционные японские десерты готовятся только из риса","Для их приготовления часто используется зелёный чай матча, рисовая мука и фасолевая паста","В них важен баланс вкуса, а не просто сладость"]},{"id":"94526-4","text":"Почему итальянская кухня известна своей простотой?","type":"multiple","options":["Она основана на использовании свежих натуральных ингредиентов и простых рецептах","Большинство традиционных блюд включают не более 3-5 основных компонентов","Итальянцы готовят блюда исключительно по старинным рецептам без изменений"]},{"id":"94526-5","text":"Какое правило испанцы соблюдают при употреблении вина?","type":"single","options":["Вино пьют медленно, смакуя вкус, и всегда в компании","В Испании запрещено смешивать вино с другими напитками","Вино пьют исключительно во время обеда и ужина"]},{"id":"94526-6","text":"Что является одной из главных особенностей французской кулинарной культуры?","type":"single","options":["Вся французская кухня основана на использовании специй и сложных маринадов","Французы предпочитают есть на бегу, уделяя минимум внимания подаче блюд","Каждый приём пищи — это ритуал, который включает несколько смен блюд и неспешное наслаждение вкусом"]},{"id":"94526-7","text":"Какой принцип сочетаемости продуктов важен в итальянской гастрономической культуре?","type":"multiple","options":["Итальянцы не используют специи, чтобы не перебивать вкус основного продукта","Разные виды пасты подаются только с конкретными соусами","Каждое блюдо сопровождается вином, подобранным в соответствии с его вкусом","В Италии запрещено сочетать мясо с томатными соусами"]},{"id":"94526-8","text":"Что делает хамон иберико самым элитным видом ветчины в Испании?","type":"single","options":["Он выдерживается не менее 20 лет перед употреблением","Его готовят только в одном регионе Испании","Свиньи питаются исключительно желудями, что придаёт мясу особый вкус"]},{"id":"94526-9","text":"Какие традиции связаны с употреблением саке?","type":"multiple","options":["Саке принято наливать друг другу, а не себе, как знак уважения","Его можно подавать как горячим, так и охлаждённым, в зависимости от сорта","Саке употребляют исключительно в больших количествах","Саке подают только во время религиозных церемоний"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('95485','test','Тест по винам','guru-44607','{"id":"95485","title":"Тест по винам","timeLimitSeconds":520,"passCount":13,"questions":[{"id":"95485-1","text":"Какой сорт даёт вина с мощными танинами и нотами чернослива, перца и дыма?","type":"single","options":["Мерло","Пино Нуар","Каберне Совиньон","Шираз (Сира)"]},{"id":"95485-2","text":"Какой сорт является основой для испанских вин Приората и ключевым сортом Южной Роны?","type":"single","options":["Гарнача (Гренаш)","Мерло","Каберне Совиньон","Пино Нуар"]},{"id":"95485-3","text":"Какой итальянский сорт является основой Просекко?","type":"single","options":["Пино Гриджио","Рислинг","Глера","Шардоне"]},{"id":"95485-4","text":"Какой сорт винограда известен своими высокими танинами и ароматами чёрной смородины, зелёного перца и кедра?","type":"single","options":["Каберне Совиньон","Пино Нуар","Мерло","Неббиоло"]},{"id":"95485-5","text":"Какой белый сорт винограда входит в «золотую тройку» и известен своей универсальностью?","type":"single","options":["Шардоне","Гевюрцтраминер","Рислинг","Совиньон Блан"]},{"id":"95485-6","text":"Какой сорт часто купажируется с Каберне и известен своей бархатистой текстурой?","type":"single","options":["Неббиоло","Мерло","Пино Нуар","Каберне Совиньон"]},{"id":"95485-7","text":"Какой сорт винограда требует длительной выдержки для смягчения танинов и известен высокой кислотностью?","type":"single","options":["Неббиоло","Каберне Совиньон","Мерло","Пино Нуар"]},{"id":"95485-8","text":"Какой сорт винограда считается основой для многих лучших вин Испании и Португалии?","type":"single","options":["Мерло","Темпранильо","Каберне Совиньон","Пино Нуар"]},{"id":"95485-9","text":"Какой сорт игристого вина производится в Ломбардии и известен классическим методом?","type":"single","options":["Кава","Креман","Франчакорта","Шампанское"]},{"id":"95485-10","text":"Какой сорт винограда известен джемовыми ароматами ежевики, лакрицы и корицы?","type":"single","options":["Каберне Совиньон","Пино Нуар","Мерло","Зинфандель"]},{"id":"95485-11","text":"Какой метод используется для производства Просекко?","type":"single","options":["Сабраж","Метод Шарма","Резервуарный метод","Классический метод"]},{"id":"95485-12","text":"Какое игристое вино сделано классическим методом из автохтонных сортов макабео, щарелло и парельяда?","type":"single","options":["Шампанское","Франчакорта","Кава","Креман"]},{"id":"95485-13","text":"Какой сорт известен своей кислотностью и нотами свежескошенной травы, грейпфрута и крыжовника?","type":"single","options":["Гевюрцтраминер","Шардоне","Совиньон Блан","Рислинг"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('80505','test','Тест водка','guru-36651','{"id":"80505","title":"Тест водка","timeLimitSeconds":150,"passCount":7,"questions":[{"id":"80505-1","text":"Является ли водка хорошей основой для коктейлей?","type":"single","options":["Нет","Да"]},{"id":"80505-2","text":"Водка - это...","type":"single","options":["Дистиллят","Ректификат"]},{"id":"80505-3","text":"Какое отношение имеет Д. М. Менделеев к водке?","type":"single","options":["Он её изобрел","Он любил её выпивать","Он защитил диссертацию, в которой указал что водка есть смесь зернового спирта разведенного по весу водой до 40%","Он изобрел ректификационную колону для перегонки"]},{"id":"80505-4","text":"Как назывался прародитель водки?","type":"single","options":["Аквавита","Все ответы верны","Хлебное Вино"]},{"id":"80505-5","text":"При производстве какого спирта не используют картофель?","type":"single","options":["Экстра","Спирт Высшей Очистки","Люкс","Альфа"]},{"id":"80505-6","text":"Лучшее сырьё для производства водки - это...","type":"single","options":["Зерновые культуры","Меласса","Картофель","Свекла"]},{"id":"80505-7","text":"Самый распространенный спирт, использующийся при изготовлении водки - это ...","type":"single","options":["Альфа","Спирт высшей очистки","Экстра","Люкс"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('105355','test','Тест джин','guru-36651','{"id":"105355","title":"Тест джин","timeLimitSeconds":210,"passCount":7,"questions":[{"id":"105355-1","text":"С каким напитком чаще всего смешивают джин для раскрытия его вкуса и качеств?","type":"single","options":["Лимонный сок","Тоник","Содовая","Имбирный эль"]},{"id":"105355-2","text":"Как назывался предшественник современного джина, появившийся в Голландии?","type":"single","options":["Женевер","Лондон драй","Олд том","Сло джин"]},{"id":"105355-3","text":"Какова минимальная крепость джина по законам Англии?","type":"single","options":["40.00%","37.50%","35.00%","42.50%"]},{"id":"105355-4","text":"Какой вид джина считается самым строгим стандартом, запрещающим любые добавки после дистилляции?","type":"single","options":["Plymouth Gin","Yellow Gin","Old Tom Gin","London Dry Gin"]},{"id":"105355-5","text":"Какая разновидность джина имеет рубиново-красный оттенок и крепость около 30%, получаемую за счёт добавления терновых ягод?","type":"single","options":["Sloe Gin","Plymouth Gin","Distilled Gin","Yellow Gin"]},{"id":"105355-6","text":"Как называется традиционный английский джин, подслащенный сахарным сиропом, название которого связано с деревянным аппаратом в форме кота?","type":"single","options":["Old Tom Gin","Plymouth Gin","Sloe Gin","Yellow Gin"]},{"id":"105355-7","text":"Какое растительное сырьё является обязательным для производства джина?","type":"single","options":["Цитрусовые корки","Можжевеловые ягоды","Кориандр","Терновые ягоды"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('105354','test','Тест текила','guru-36651','{"id":"105354","title":"Тест текила","timeLimitSeconds":210,"passCount":7,"questions":[{"id":"105354-1","text":"Как называется сердцевина агавы, используемая в производстве текилы?","type":"single","options":["Corazón","Piña","Piramide","Agave heart"]},{"id":"105354-2","text":"Какое растение служит основным сырьём для производства текилы?","type":"single","options":["Голубая агава","Сахарный тростник","Кактус","Голубая юкка"]},{"id":"105354-3","text":"Как называют сборщиков урожая агавы?","type":"single","options":["Пинадоры","Химадоры","Кампесинос","Агаверос"]},{"id":"105354-4","text":"Какой из перечисленных способов употребления текилы является традиционным за пределами Мексики?","type":"single","options":["С солью и лаймом","С сангритой","С медом и лимоном","С корицей и апельсином"]},{"id":"105354-5","text":"Что означает маркировка «100% de agave» на бутылке текилы?","type":"single","options":["Напиток разлит за пределами Мексики","Текила выдержана не менее 3 лет","Напиток изготовлен исключительно из сока голубой агавы","В составе не менее 51% сахаров агавы"]},{"id":"105354-6","text":"Как называется текила, которую разливают по бутылкам сразу после перегонки или выдерживают не более двух месяцев?","type":"single","options":["Blanco (Plata)","Extra Anejo","Anejo","Reposado"]},{"id":"105354-7","text":"Какая выдержка требуется для текилы категории Anejo?","type":"single","options":["Не менее 3 лет","Не менее 1 года и не более 3 лет","Не более 2 месяцев","Не менее 2 месяцев и не более 1 года"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('93157','test','Тест 1','guru-43399','{"id":"93157","title":"Тест 1","timeLimitSeconds":240,"passCount":8,"questions":[{"id":"93157-1","text":"Что включают в себя внутренние мотиваторы?","type":"single","options":["Признание со стороны руководства","Финансовые вознаграждения и поощрения","Личные амбиции, желания и ценности сотрудников","Стремление к удовлетворению физиологических потребностей"],"image":"assets/remaining-tests/47b49582a31d31f747f446f9.jpg","images":["assets/remaining-tests/47b49582a31d31f747f446f9.jpg"]},{"id":"93157-2","text":"Как мотивированные сотрудники влияют на текучесть персонала в компании?","type":"single","options":["Увеличивают текучесть персонала","Снижают текучесть персонала","Текучесть персонала зависит только от заработной платы","Не оказывают влияния на текучесть персонала"],"image":"assets/remaining-tests/f7aa9e82614373f7afda2c2e.jpg","images":["assets/remaining-tests/f7aa9e82614373f7afda2c2e.jpg"]},{"id":"93157-3","text":"Какие факторы относятся к факторам удовлетворения в теории Герцберга?","type":"multiple","options":["Ощущение достижения","Условия работы","Личный рост","Заработная плата"],"image":"assets/remaining-tests/3bd493da96f0aa8345355c9b.jpg","images":["assets/remaining-tests/3bd493da96f0aa8345355c9b.jpg"]},{"id":"93157-4","text":"Что такое материальная мотивация?","type":"single","options":["Система мотивации, основанная на обеспечении комфортных условий работы","Метод стимулирования сотрудников путем предоставления дополнительных образовательных возможностей","Форма стимулирования сотрудников, основанная на предоставлении финансовых вознаграждений или материальных благ","Технология мотивации коллектива путем проведения корпоративных мероприятий"],"image":"assets/remaining-tests/6d6f4ec791c502667e9ffedd.jpg","images":["assets/remaining-tests/6d6f4ec791c502667e9ffedd.jpg"]},{"id":"93157-5","text":"Как менеджеры в ресторанной индустрии могут удовлетворять физиологические потребности сотрудников?","type":"single","options":["Предоставление перерывов и еды","Установление строгих сроков","Признание со стороны руководства","Обеспечение социальной принадлежности"],"image":"assets/remaining-tests/061471be5e8e2ac3f1fcf7e3.jpg","images":["assets/remaining-tests/061471be5e8e2ac3f1fcf7e3.jpg"]},{"id":"93157-6","text":"Какие факторы могут оказывать влияние на эффективность материальной мотивации?","type":"multiple","options":["Отсутствие возможности карьерного роста","Справедливость распределения вознаграждений","Прозрачность системы стимулирования","Недостаток информации о достижениях сотрудников"],"image":"assets/remaining-tests/cdd9cc6399e28e0c401f5b90.jpg","images":["assets/remaining-tests/cdd9cc6399e28e0c401f5b90.jpg"]},{"id":"93157-7","text":"Почему понимание уровней мотивации сотрудника важно для менеджеров в ресторанной индустрии?","type":"single","options":["Для создания соответствующей мотивационной стратегии","Для удовлетворения физиологических потребностей","Для установления строгих сроков"],"image":"assets/remaining-tests/891fc4604a52de4130284197.jpg","images":["assets/remaining-tests/891fc4604a52de4130284197.jpg"]},{"id":"93157-8","text":"Какие инструменты нематериальной мотивации могут повысить уровень удовлетворенности и мотивации на работе?","type":"single","options":["Карьерный рост","Слова благодарности","Обучение и развитие","Все варианты","Создание увлекательной рабочей среды"],"image":"assets/remaining-tests/dd766ecb0fc402bd26c3f44f.jpg","images":["assets/remaining-tests/dd766ecb0fc402bd26c3f44f.jpg"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('93158','test','Тест 2','guru-43399','{"id":"93158","title":"Тест 2","timeLimitSeconds":180,"passCount":6,"questions":[{"id":"93158-1","text":"Какие рекомендации даны для применения теории ожидания Врума на практике в ресторане?","type":"single","options":["Построение мотивации на основе карьерного роста, предоставление ясных целей и поддержки в их достижении","Ограничение обратной связи с сотрудниками","Установление строгих сроков"],"image":"assets/remaining-tests/5c10492a9f3c166786aea25c.jpg","images":["assets/remaining-tests/5c10492a9f3c166786aea25c.jpg"]},{"id":"93158-2","text":"Почему факторы удовлетворения и неудовлетворения в теории Герцберга называют независимыми друг от друга?","type":"single","options":["Потому что они не связаны с работой сотрудников","Потому что увеличение факторов удовлетворения не обязательно уменьшит неудовлетворение","Потому что они зависят только от вознаграждения"],"image":"assets/remaining-tests/f85028b0ea35343f67597845.jpg","images":["assets/remaining-tests/f85028b0ea35343f67597845.jpg"]},{"id":"93158-3","text":"Как менеджеры ресторана могут применять теорию Герцберга на практике?","type":"single","options":["Иногда проводить проверки","Использовать только материальные поощрения","Оповестить сотрудников о теории","Работать над созданием более удовлетворяющей среды, предоставляя возможности для саморазвития, признания и чувства ценности в команде"]},{"id":"93158-4","text":"Какие концепции включены в теорию ожидания Врума?","type":"single","options":["Ожидание, инструментальность, и значение вознаграждения","Мотивация, следствие","Ожидание и инструментальность"],"image":"assets/remaining-tests/281df76688c90bd6af7762b7.jpg","images":["assets/remaining-tests/281df76688c90bd6af7762b7.jpg"]},{"id":"93158-5","text":"Что отражает концепция \"Ожидание\" в теории Врума?","type":"single","options":["Уровень удовлетворенности сотрудника","Вера сотрудника в то, что его усилия приведут к достижению цели","Определение ценности вознаграждения","Оценка успешного достижения цели"],"image":"assets/remaining-tests/3f2b5835f5e92a05e36807d9.jpg","images":["assets/remaining-tests/3f2b5835f5e92a05e36807d9.jpg"]},{"id":"93158-6","text":"Какая концепция оценивает, насколько успешное достижение цели приведет к желаемым вознаграждениям в теории Врума?","type":"single","options":["Инструментальность","Уровень мотивации","Ожидание"],"image":"assets/remaining-tests/4d5923618090b19c75a39dd0.jpg","images":["assets/remaining-tests/4d5923618090b19c75a39dd0.jpg"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('93159','test','Тест 3','guru-43399','{"id":"93159","title":"Тест 3","timeLimitSeconds":240,"passCount":8,"questions":[{"id":"93159-1","text":"Почему важно, чтобы сотрудники разрабатывали индивидуальные планы развития?","type":"single","options":["Потому что это обязательное требование","Потому что индивидуальные планы развития могут помочь сотрудникам определить, какие навыки они хотят развивать и каким образом","Потому что сотрудники не нуждаются в развитии навыков","Потому что это только для менеджеров"],"image":"assets/remaining-tests/319befe2ca8750ddae91ba9b.jpg","images":["assets/remaining-tests/319befe2ca8750ddae91ba9b.jpg"]},{"id":"93159-2","text":"Почему открытая коммуникация важна для мотивации сотрудников в ресторанной индустрии?","type":"single","options":["Потому что сотрудники должны чувствовать, что их мнение ценится и их заботы учитываются","Потому что она обязательная по закону","Потому что сотрудники не должны знать о происходящем в ресторане","Потому что это не важно для мотивации"],"image":"assets/remaining-tests/85d9546c3f2d8a9aea559816.jpg","images":["assets/remaining-tests/85d9546c3f2d8a9aea559816.jpg"]},{"id":"93159-3","text":"Что может включать в себя поощрение за хорошую работу ?","type":"multiple","options":["подарки","бонусы","повышение","обратную связь","еще большую нагрузку"]},{"id":"93159-4","text":"сотрудникам в ресторанной индустрии?","type":"single","options":["наставничество","профессиональное развитие","все варианты","обучение и тренинги"]},{"id":"93159-5","text":"Почему важно учитывать индивидуальные мотиваторы сотрудников при применении системы признания и поощрений?","type":"single","options":["Потому что система признания и поощрений не зависит от индивидуальных мотиваторов","Потому что не всем нравится публичное признание, и некоторые могут больше ценить индивидуальную награду","Потому что все сотрудники имеют одинаковые мотиваторы","Потому что награды должны быть одинаковыми для всех сотрудников"],"image":"assets/remaining-tests/7654eb833afec281b515c196.jpg","images":["assets/remaining-tests/7654eb833afec281b515c196.jpg"]},{"id":"93159-6","text":"Каким образом сотрудники могут быть мотивированы через процент от продаж?","type":"multiple","options":["Проценты не должны отражаться на сотрудниках","Получение процента от прибыли ресторана","Получение процента от продаж определенных блюд","Получение процента от выручки при увеличении количества сотрудников"]},{"id":"93159-7","text":"Какую роль играют регулярные обзоры производительности и индивидуальная обратная связь в системе признания и поощрений?","type":"single","options":["Они не играют роли в системе признания и поощрений","Позволяют сотрудникам видеть свои сильные стороны и области для улучшения, а также понимать, как их вклад ценится и как они могут развивать свои навыки"],"image":"assets/remaining-tests/d57b58ee1a85dbc46a83c22b.jpg","images":["assets/remaining-tests/d57b58ee1a85dbc46a83c22b.jpg"]},{"id":"93159-8","text":"Что может включать повышение заработной платы в рамках мотивации персонала?","type":"single","options":["Выплата больничных","Увеличение зарплаты только для руководителей","Увеличение зарплаты сотрудника на основе его производительности и стажа работы"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('93160','test','Тест 4','guru-43399','{"id":"93160","title":"Тест 4","timeLimitSeconds":210,"passCount":7,"questions":[{"id":"93160-1","text":"Какие методы оценки мотивации могут быть использованы при мониторинге персонала в ресторанной индустрии?","type":"multiple","options":["анализ текучести кадров","интервью","слухи и сарафанное радио","Анкеты и опросники","оценка производительности"]},{"id":"93160-2","text":"Зачем предлагается рассмотреть выходное интервью в контексте данного курса?","type":"single","options":["Как метод подбора новых сотрудников.","Как средство увольнения сотрудников","Как инструмент пост-мотивации сотрудников."],"image":"assets/remaining-tests/6f54bc1be2085be9c45f4f6c.jpg","images":["assets/remaining-tests/6f54bc1be2085be9c45f4f6c.jpg"]},{"id":"93160-3","text":"Что является возможным результатом успешного выходного интервью сотрудника?","type":"single","options":["Освобождение рабочих мест.","Укрепление мотивации и преданности коллектива.","Общая депрессия в коллективе."],"image":"assets/remaining-tests/cb79167b309a5ea0bd5e25c4.jpg","images":["assets/remaining-tests/cb79167b309a5ea0bd5e25c4.jpg"]},{"id":"93160-4","text":"Зачем проводить анализ текучести кадров при мониторинге мотивации?","type":"single","options":["Для создания новых вакансий","Только для статистики","Для увеличения текучести кадров","Для выявления, почему сотрудники уходят с работы и какие факторы могли повлиять на их решение"],"image":"assets/remaining-tests/d35da50fee5d341edeb72354.jpg","images":["assets/remaining-tests/d35da50fee5d341edeb72354.jpg"]},{"id":"93160-5","text":"Что может включать в себя адаптация мотивационных стратегий во времена перемен?","type":"single","options":["Оставление всего без изменений.","Более частые обратные связи, поддержка и увеличение прозрачности.","Игнорирование потребностей сотрудников."],"image":"assets/remaining-tests/63169108f0da0a37756c6271.jpg","images":["assets/remaining-tests/63169108f0da0a37756c6271.jpg"]},{"id":"93160-6","text":"Что включает в себя долгосрочное управление мотивацией?","type":"single","options":["Установление долгосрочных целей и разработка мотивационных программ.","Краткосрочные цели и отсутствие плана.","Невнимание к потребностям сотрудников на долгосрочной перспективе."],"image":"assets/remaining-tests/b7eaafb0033c133ec7570436.jpg","images":["assets/remaining-tests/b7eaafb0033c133ec7570436.jpg"]},{"id":"93160-7","text":"Зачем устанавливать долгосрочные цели в управлении мотивацией?","type":"single","options":["Задача установления долгосрочных целей не имеет смысла.","Для определения, какие цели связаны с мотивацией сотрудников, например, уменьшение текучести кадров или повышение производительности.","Чтобы усложнить процесс управления."],"image":"assets/remaining-tests/2fee0877a8e51ec35b830d87.jpg","images":["assets/remaining-tests/2fee0877a8e51ec35b830d87.jpg"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('56097','test','Тест к Уроку 1. Рабочий день администратора.','guru-25811','{"id":"56097","title":"Тест к Уроку 1. Рабочий день администратора.","timeLimitSeconds":240,"passCount":8,"questions":[{"id":"56097-1","text":"В чем заключается миссия менеджера смены?","type":"single","options":["В том, чтобы вовремя отметить время прихода каждого сотрудника, дать конструктивную обратную связь опоздавшим на смену.","Быть проводником и амбассадором ценностей ресторана для гостей и сотрудников.","Чтобы все поставки продуктов в ресторане были приняты вовремя и должным образом."],"image":"assets/remaining-tests/ebb1ca80a2df4abe397cf42a.jpg","images":["assets/remaining-tests/ebb1ca80a2df4abe397cf42a.jpg"]},{"id":"56097-2","text":"Для чего администратору нужен заполненный чеклист открытия?","type":"single","options":["Для того, чтобы показать своим сотрудникам, что они плохо и мало работают.","Для того, чтобы предъявить его руководству.","Для того, чтобы понять, готова ли смена к работе и успеть исправить недоработки."],"image":"assets/remaining-tests/d87c720e81c880dfb0225c62.jpg","images":["assets/remaining-tests/d87c720e81c880dfb0225c62.jpg"]},{"id":"56097-3","text":"Отметьте вариант ответа, который не входит в основные задачи администратора","type":"single","options":["набирать и обучать линейный персонал зала (официанты, бармены, бариста, хостес).","вести смену в ресторане с помощью установленных инструментов и давать сотрудникам обратную связь по ним.","Знать наизусть номера телефонов всех подрядчиков по ремонту оборудования.","быть проводником и амбассадором ценностей ресторана для гостей и сотрудников."],"image":"assets/remaining-tests/adc0a338247d36907b288baa.jpg","images":["assets/remaining-tests/adc0a338247d36907b288baa.jpg"]},{"id":"56097-4","text":"Когда лучше всего заниматься HR - вопросами (набором новых сотрудников, развивающими беседами с опытными сотрудниками, анализом обученности и подготовкой к собраниям и тренингам)?","type":"single","options":["После бизнес-ланча до вечернего наплыва гостей, с 16 до 18.","Перед закрытием ресторана.","Во время бизнес-ланча, когда официанты заняты работой с гостями."],"image":"assets/remaining-tests/9f96bbc6e3c7855de10ead4c.jpg","images":["assets/remaining-tests/9f96bbc6e3c7855de10ead4c.jpg"]},{"id":"56097-5","text":"Что должен делать менеджер смены в \"запару\"?","type":"single","options":["Заниматься ежедневной документацией.","Координировать работу официантов, быть в зале и общаться с гостями.","Самому брать столы и обслуживать гостей."],"image":"assets/remaining-tests/d7e0e5f48490b887683253a7.jpg","images":["assets/remaining-tests/d7e0e5f48490b887683253a7.jpg"]},{"id":"56097-6","text":"За сколько минут до открытия ресторана нужно проверить утренние чеклисты по всем позициям?","type":"single","options":["Максимум за 15 минут до открытия.","Минимум за 10 минут до открытия.","Максимум за полчаса до открытия."],"image":"assets/remaining-tests/444bc539eddcf631387848de.jpg","images":["assets/remaining-tests/444bc539eddcf631387848de.jpg"]},{"id":"56097-7","text":"Когда лучше всего заниматься текущими делами (переговорами с поставщиками, мониторингом цен) и выполнением поручений руководства?","type":"single","options":["После бизнес-ланча.","В вечерние часы, перед закрытием.","В свободные часы до начала ланча."],"image":"assets/remaining-tests/86bc2bdc001d459e3df4040a.jpg","images":["assets/remaining-tests/86bc2bdc001d459e3df4040a.jpg"]},{"id":"56097-8","text":"Нужно ли ругать сотрудника, который опоздал на смену на 3 минуты?","type":"single","options":["Ругать не нужно, но необходимо дать обратную связь, чтобы человек понял, что поступил неправильно.","Нет, не нужно. Всего три минуты - это не сильное опоздание.","Да, нужно, при всех. Чтобы все поняли, что опоздание на смену - серьезный проступок."],"image":"assets/remaining-tests/f341bfec2692f6f4895c7340.jpg","images":["assets/remaining-tests/f341bfec2692f6f4895c7340.jpg"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('56098','test','Тест к уроку 2. Пятиминутки.','guru-25811','{"id":"56098","title":"Тест к уроку 2. Пятиминутки.","timeLimitSeconds":300,"passCount":10,"questions":[{"id":"56098-1","text":"С чего следует начинать собрание-пятиминутку?","type":"single","options":["С озвучивания поручений по уборке","С обмена хорошими новостями","С озвучивания стоп-листа"],"image":"assets/remaining-tests/69e3ffe0954ffdcc5f13800e.jpg","images":["assets/remaining-tests/69e3ffe0954ffdcc5f13800e.jpg"]},{"id":"56098-2","text":"Уберите лишнее из алгоритма проведения пятиминутки:","type":"single","options":["Озвучиваем штрафные санкции за невыполнение целей.","Озвучиваем меню бизнес-ланча.","Распределяем ребят по позициям в зале.","Озвучиваем стоп-листы по всем позициям."],"image":"assets/remaining-tests/5a708a7f17b9d0adc04d2556.jpg","images":["assets/remaining-tests/5a708a7f17b9d0adc04d2556.jpg"]},{"id":"56098-3","text":"Как на пятиминутке лучше всего проверить, знает ли команда меню бизнес-ланча на день?","type":"single","options":["Дать каждому написать тест по меню бизнес-ланча.","Устроить блиц-опрос по ингредиентам меню ланча на пятиминутке.","После пятиминутки заставить каждого сдать письменную мини-аттестацию по меню."],"image":"assets/remaining-tests/4c8c26b75913ef76e30f342a.jpg","images":["assets/remaining-tests/4c8c26b75913ef76e30f342a.jpg"]},{"id":"56098-4","text":"Уберите лишнее из алгоритма проведения пятиминутки:","type":"single","options":["Наказываем всех опоздавших.","Озвучиваем финансовые результаты предыдущего дня.","Озвучиваем цели на текущий день.","Начинаем с хорошей новости."],"image":"assets/remaining-tests/103994170a907b717857b86a.jpg","images":["assets/remaining-tests/103994170a907b717857b86a.jpg"]},{"id":"56098-5","text":"Уберите лишнее из нижеперечисленных правил проведения пятиминуток:","type":"single","options":["Проводить всегда стоя.","Начинать всегда вовремя.","Длится не менее 30 минут."],"image":"assets/remaining-tests/58d1c50037af500397f2a29c.jpg","images":["assets/remaining-tests/58d1c50037af500397f2a29c.jpg"]},{"id":"56098-6","text":"Для чего нужны пятиминутки?","type":"single","options":["Они нужны для того, чтобы озвучить стоп-лист, старт-лист, и рассказать про брони и мероприятия на день","Пятиминутки нужны для того, чтобы раздать всем задания по уборке на день и проконтролировать внешний вид каждого сотрудника.","они способствуют поддержанию дисциплины и способны зарядить всю смену хорошим настроением и важной информаций"],"image":"assets/remaining-tests/3742d36a16acfbe2167d2a7b.jpg","images":["assets/remaining-tests/3742d36a16acfbe2167d2a7b.jpg"]},{"id":"56098-7","text":"Нужно ли на пятиминутке озвучить цель на день по выручке?","type":"single","options":["Нет, это не нужно. С целями ресторана по выручке должны быть ознакомлены только менеджеры.","Да, обязательно. Каждый член команды должен чувствовать себя ответственным за результаты совместной работы."],"image":"assets/remaining-tests/acfc8ad5130b394386561434.jpg","images":["assets/remaining-tests/acfc8ad5130b394386561434.jpg"]},{"id":"56098-8","text":"Чего не стоит делать во время пятиминутки?","type":"multiple","options":["Озвучивать выручку за предыдущий день - это коммерческая тайна.","Делиться своими личными хорошими новостями с командой.","Зевать и стоять вразвалку, сидеть в мобильном телефоне.","Поднимать вопросы, которые решаются в рабочем порядке, без привлечения всех участников совещания"],"image":"assets/remaining-tests/ea1362202a168f00008dc862.jpg","images":["assets/remaining-tests/ea1362202a168f00008dc862.jpg"]},{"id":"56098-9","text":"Сколько по времени должна длиться пятиминутка?","type":"single","options":["40 минут будет достачно для обсуждения всех важных вопросов","20-25 минут оптимальное время для утреннего собрания.","Не больше 10 минут вместе с вопросами от команды"],"image":"assets/remaining-tests/10d69c8552b46a1d2bd54b90.jpg","images":["assets/remaining-tests/10d69c8552b46a1d2bd54b90.jpg"]},{"id":"56098-10","text":"Нужно-ли озвучивать на пятиминутке финансовые результаты предыдущей смены?","type":"single","options":["Нет, ни в коем случае. Цифры должны знать только администраторы, управляющий и бухгалтер!","Да, нужно. Это дает ребятам почувствовать свою причастность к общим финансовым результатам."],"image":"assets/remaining-tests/9b1ab3b2f6c61cbe81721cc1.jpg","images":["assets/remaining-tests/9b1ab3b2f6c61cbe81721cc1.jpg"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
